const MAP_PALETTES=[
  ['dorado','Dorado Elegante','#a66b0a','#faf5eb','#342c23','#d9c398'],['navy','Azul Navy','#1b2a4a','#f3f4f7','#19243b','#b8c2d1'],['verde_olivo','Verde Olivo','#6b7840','#f4f5eb','#303a26','#b6bf94'],['celeste','Celeste','#4d78a8','#f1f7fb','#263d54','#b4cfe2'],['terracota','Terracota','#b5684a','#fbf1e9','#492e26','#d9ae8e'],['rojo','Rojo Clásico','#8c2323','#fbf3ef','#472526','#d6aaaa'],['verde_esmeralda','Verde Esmeralda','#27895a','#eef7f1','#1e3d2c','#a9d3b6'],['rosado','Rosado','#ac517c','#fff4f7','#593044','#e7b8ca'],['multicolor','Multicolor','#ba4664','#fff5ea','#4c3546','#e7b173']
];
const xml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function mermaidFor(diagram){const byId=Object.fromEntries(diagram.nodes.map(node=>[node.id,node]));return ['flowchart LR',...diagram.nodes.map(node=>`  ${node.id}${node.type==='decision'?'{':node.type==='store'?'[(':'['}"${node.title}${node.type==='observed'?' — UI OBSERVADA':''}${node.type==='pending'?' — PENDIENTE':''}"${node.type==='decision'?'}':node.type==='store'?')]':']'}`),...diagram.edges.map(edge=>`  ${edge.from} ${byId[edge.from].type==='pending'||byId[edge.to].type==='pending'?'-.->':'-->'}${edge.label?`|"${edge.label}"|`:''} ${edge.to}`)].join('\n');}
function svgFor(diagram){
  const byId=Object.fromEntries(diagram.nodes.map(node=>[node.id,node]));
  const edges=diagram.edges.map(edge=>{const a=byId[edge.from],b=byId[edge.to];let start,end,points;
    if(edge.via.length){const first=edge.via[0],last=edge.via.at(-1);start=Math.abs(first[0]-(a.x+a.w/2))>Math.abs(first[1]-(a.y+a.h/2))?[first[0]>a.x+a.w/2?a.x+a.w:a.x,a.y+a.h/2]:[a.x+a.w/2,first[1]>a.y+a.h/2?a.y+a.h:a.y];end=Math.abs(last[0]-(b.x+b.w/2))>Math.abs(last[1]-(b.y+b.h/2))?[last[0]>b.x+b.w/2?b.x+b.w:b.x,b.y+b.h/2]:[b.x+b.w/2,last[1]>b.y+b.h/2?b.y+b.h:b.y];points=[start,...edge.via,end];}
    else if(a.y===b.y){start=[a.x+(b.x>a.x?a.w:0),a.y+a.h/2];end=[b.x+(b.x>a.x?0:b.w),b.y+b.h/2];points=[start,end];}
    else {start=[a.x+a.w/2,b.y>a.y?a.y+a.h:a.y];end=[b.x+b.w/2,b.y>a.y?b.y:b.y+b.h];const mid=(start[1]+end[1])/2;points=[start,[start[0],mid],[end[0],mid],end];}
    const p=points[Math.floor((points.length-1)/2)],q=points[Math.ceil((points.length-1)/2)];const lx=(p[0]+q[0])/2,ly=(p[1]+q[1])/2;
    return `<path d="${points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')}" fill="none" stroke="#89938b" stroke-width="1.6" ${a.type==='pending'||b.type==='pending'?'stroke-dasharray="5 4"':''} marker-end="url(#arrow)"/>${edge.label?`<rect x="${lx-edge.label.length*3.5-5}" y="${ly-11}" width="${edge.label.length*7+10}" height="20" fill="#fff"/><text x="${lx}" y="${ly+3}" text-anchor="middle" font-size="11" fill="#60685e">${xml(edge.label)}</text>`:''}`;
  }).join('');
  const colors={local:['#edf4ed','#78907b'],store:['#e9f0f6','#6d899c'],decision:['#f9edcf','#a98232'],pending:['#f5ece7','#ac7664'],observed:['#e9f1f8','#64829d'],error:['#faeeee','#b67b75']};
  const nodes=diagram.nodes.map(node=>{const [fill,stroke]=colors[node.type];let shape;
    if(node.type==='decision')shape=`<path d="M${node.x+20} ${node.y} H${node.x+node.w-20} L${node.x+node.w} ${node.y+node.h/2} L${node.x+node.w-20} ${node.y+node.h} H${node.x+20} L${node.x} ${node.y+node.h/2} Z"/>`;
    else shape=`<rect x="${node.x}" y="${node.y}" width="${node.w}" height="${node.h}" rx="${node.type==='store'?15:5}"/>`;
    return `<g><g fill="${fill}" stroke="${stroke}" stroke-width="1.2" ${node.type==='pending'?'stroke-dasharray="5 4"':''}>${shape}</g><text x="${node.x+node.w/2}" y="${node.y+32}" font-size="15" font-weight="600" fill="#28352e" text-anchor="middle">${xml(node.title)}</text><text x="${node.x+node.w/2}" y="${node.y+55}" font-size="11" fill="#58645a" text-anchor="middle">${xml(node.note)}</text></g>`;
  }).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 ${diagram.height}" role="img" aria-labelledby="svg-title svg-desc" font-family="Arial, sans-serif"><title id="svg-title">${xml(diagram.title)}</title><desc id="svg-desc">${xml(diagram.description)}. ${xml(diagram.edges.map(x=>`${byId[x.from].title} a ${byId[x.to].title}${x.label?': '+x.label:''}`).join('. '))}</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7 Z" fill="#89938b"/></marker></defs><rect width="1200" height="${diagram.height}" fill="#fff"/>${edges}${nodes}</svg>`;
}
if(typeof module!=='undefined' && module.exports)module.exports={SYSTEM_DIAGRAMS,MAP_PALETTES,svgFor,mermaidFor};
if(typeof document!=='undefined'){
  let current=SYSTEM_DIAGRAMS[0],zoom=0,palette=MAP_PALETTES[0];
  const $=id=>document.getElementById(id);
  const download=(name,content,type)=>{const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  function render(){document.querySelector('.tabs').innerHTML=SYSTEM_DIAGRAMS.map(d=>`<button data-diagram="${d.id}" aria-pressed="${d.id===current.id}">${d.name}</button>`).join('');$('diagram-kicker').textContent=current.name;$('diagram-title').textContent=current.title;$('diagram-description').textContent=current.description;$('canvas').innerHTML=svgFor(current);$('diagram-notes').innerHTML=current.notes.map(([title,text])=>`<p><strong>${xml(title)}</strong>${xml(text)}</p>`).join('');$('source').textContent=mermaidFor(current);zoom=0;resize();}
  function resize(){const svg=$('canvas').querySelector('svg');svg.style.width=zoom?`${1200*zoom}px`:'100%';$('zoom-level').textContent=zoom?`${Math.round(zoom*100)}%`:'Ajustado';}
  document.querySelector('.tabs').addEventListener('click',event=>{const button=event.target.closest('[data-diagram]');if(!button)return;current=SYSTEM_DIAGRAMS.find(d=>d.id===button.dataset.diagram);history.replaceState(null,'',`#${current.id}`);render();});
  $('zoom-in').onclick=()=>{zoom=Math.min(2,(zoom||$('canvas').clientWidth/1200)+.2);resize();};$('zoom-out').onclick=()=>{zoom=Math.max(.4,(zoom||$('canvas').clientWidth/1200)-.2);resize();};$('fit').onclick=()=>{zoom=0;resize();};$('print').onclick=()=>window.print();
  $('download-svg').onclick=()=>download(`nupcial-${current.id}.svg`,svgFor(current),'image/svg+xml;charset=utf-8');$('download-source').onclick=()=>download(`nupcial-${current.id}.mmd`,mermaidFor(current),'text/plain;charset=utf-8');
  function renderPalette(){const [id,name,color,paper,ink,accent]=palette;$('palette-choices').innerHTML=MAP_PALETTES.map(p=>`<button style="--swatch:${p[2]}" data-palette="${p[0]}" aria-label="${p[1]}" title="${p[1]}" aria-pressed="${id===p[0]}"><span></span></button>`).join('');$('palette-preview').setAttribute('style',`--sample-color:${color};--sample-paper:${paper};--sample-ink:${ink};--sample-accent:${accent}`);$('palette-tokens').innerHTML=`<strong>${name}</strong>`+[[color,'Principal'],[paper,'Fondo'],[ink,'Texto'],[accent,'Adorno']].map(([value,role])=>`<span><i style="background:${value}"></i>${role} <code>${value}</code></span>`).join('');}
  $('palette-choices').onclick=event=>{const button=event.target.closest('[data-palette]');if(button){palette=MAP_PALETTES.find(p=>p[0]===button.dataset.palette);renderPalette();}};
  $('palette-try').onclick=()=>{location.href=`../index.html#/playground?tema=versalles&paleta=${palette[0]}`;};
  current=SYSTEM_DIAGRAMS.find(d=>d.id===location.hash.slice(1))||current;render();renderPalette();
}
